/**
 * Generates the SVG element g which will contain the data visualisation.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 * @param {object} margin The desired margins around the graph
 */
export function margeG (g, margin) {
  g.attr('transform',
    'translate(' + margin.left + ',' + margin.top + ')')
}

/**
 * Sets the size of the SVG canvas containing the graph.
 *
 * @param {number} width The desired width
 * @param {number} height The desired height
 */
export function setCanvasSize (width, height) {
  d3.select('.film-impact-svg')
    .attr('width', width)
    .attr('height', height)
}

/**
 * Appends an SVG g element which will contain the axes.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 */
export function appendAxes (g) {
  g.append('g')
    .attr('class', 'x axis')

  g.append('g')
    .attr('class', 'y axis')
}
/**
 * Appends the labels for the the y axis and the title of the graph.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 */
export function appendGraphLabels (g) {
  g.append('text')
    .text('Box Office (%)')
    .attr('class', 'y axis-text')
    .attr('transform', 'rotate(-90)')
    .attr('font-size', 16)

  g.append('text')
    .text('Année de Parution')
    .attr('class', 'x axis-text')
    .attr('font-size', 16)
}

/**
 * Appends the labels for the the y axis and the title of the graph.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 * @param {string} labelString - The new text to display as the Y-axis label
 */
export function resetYLabel (g, labelString) {
  const LABEL_MATCH = {
    box_office: 'Box Office',
    profit: 'Profit Généré',
    rating: 'Classement IMDB',
    numNominations: 'Nombre de Nominations'
  }

  const cleanString = LABEL_MATCH[labelString] || labelString

  g.select('.y.axis-text')
    .style('font-size', '16px')
    .text(cleanString + ' (%)')
}

/**
 * Positions the x axis label and y axis label.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 * @param {number} width The width of the graph
 * @param {number} height The height of the graph
 */
export function positionLabels (g, width, height) {
  g.select('.x.axis-text')
    .attr('text-anchor', 'middle')
    .attr('transform', 'translate(' + width / 2 + ', ' + (height + 50) + ')')

  g.select('.y.axis-text')
    .attr('text-anchor', 'middle')
    .attr('transform', 'translate(-50, ' + height / 2 + ')rotate(-90)')
}

/**
 * Draws the X axis at the bottom of the diagram.
 *
 * @param {*} xScale The scale to use to draw the axis
 * @param {number} height The height of the graphic
 */
export function drawXAxis (xScale, height) {
  d3.select('.x.axis')
    .attr('transform', 'translate( 0, ' + height + ')')
    .call(d3.axisBottom(xScale)
      .tickSizeOuter(0)
      .ticks(10)
      .tickFormat(d3.format('d')))
    .selectAll('text')
    .style('font-size', '12px')
}

/**
 * Draws the Y axis to the left of the diagram.
 *
 * @param {*} yScale The scale to use to draw the axis
 */
export function drawYAxis (yScale) {
  d3.select('.y.axis')
    .call(d3.axisLeft(yScale)
      .tickSizeOuter(0)
      .ticks(5)
      .tickFormat(d3.format('~s')))
    .selectAll('text')
    .style('font-size', '12px')
}
