/**
 * Sets the X scale for the visualization.
 *
 * @param {number} width - The width of the graph
 * @param {Array<string>} intervals - The intervals to be used
 * @returns {*} The linear scale in X
 */
export function setXScale (width, intervals) {
  const xScale = d3.scaleBand()
    .domain(intervals)
    .range([0, width])
    .padding(0)

  return xScale
}

/**
 * Sets the Y scale for the visualization.
 *
 * @param {number} height The height of the graph
 * @returns {*} The linear scale in Y
 */
export function setYScale (height) {
  const yScale = d3.scaleLinear()
    .domain([0, 1])
    .range([height, 0])

  return yScale
}
