/** Create the legend for the 4th visualization
 *
 * @param {Array} data - The data to display in the legend
 * @param {object} legendDiv - The DOM element to display the legend in
 * @param {Function} colorScale - The color scale to use for the legend
 * @returns {void}
 */
export function createLegend (data, legendDiv, colorScale) {
  legendDiv.selectAll('*').remove()

  // Process data to extract overcategories
  const overcategories = {}
  data.forEach(d => {
    const [overcat, undercat] = d.category.split(' : ')
    if (!overcategories[overcat]) {
      overcategories[overcat] = []
    }
    overcategories[overcat].push({
      ...d,
      undercategory: undercat
    })
  })

  const columnWidth = 200
  const itemHeight = 20
  const headerHeight = 30
  const textPadding = 20 // Space between rectangle and text

  const numOvercategories = Object.keys(overcategories).length
  const maxItems = Math.max(...Object.values(overcategories).map(group => group.length))

  legendDiv.attr('width', columnWidth * numOvercategories)
    .attr('height', headerHeight + (maxItems * itemHeight))

  let xOffset = 0

  Object.entries(overcategories).forEach(([overcat, items]) => {
    const overcatGroup = legendDiv.append('g')
      .attr('transform', `translate(${xOffset}, 0)`)

    overcatGroup.append('text')
      .text(overcat)
      .attr('x', columnWidth / 2)
      .attr('y', headerHeight - 10)
      .attr('text-anchor', 'middle')
      .style('font-weight', 'bold')
      .style('font-size', '16px')
      .style('fill', 'black')
      .style('cursor', 'pointer')
      .on('click', hideShowAllUnderlings)

    const itemGroups = overcatGroup.selectAll('.legend-item')
      .data(items)
      .enter()
      .append('g')
      .attr('class', 'legend-item')
      .attr('transform', (d, i) => `translate(${columnWidth / 2 - 50}, ${headerHeight + i * itemHeight})`)

    itemGroups.append('rect')
      .attr('width', 12)
      .attr('height', 12)
      .attr('x', 0)
      .attr('y', 5)
      .attr('rx', 3)
      .style('fill', d => colorScale(d.category))
      .style('stroke', 'black')

    itemGroups.append('text')
      .text(d => d.undercategory)
      .attr('x', textPadding)
      .attr('y', 17)
      .style('fill', 'black')
      .style('font-weight', 'bold')
      .style('font-size', '14px')
      .on('click', hideShowCategory)
      .style('cursor', 'pointer')

    xOffset += columnWidth
  })
}

/** Hide or show the given element depending of current state
 *
 * @param {MouseEvent} event - The event that triggered the hide or show
 * @param {object} d - The data to hide or show
 * @returns {void} - The function does not return anything
 */
function hideShowCategory (event, d) {
  const categoryClass = d.category.replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').toLowerCase()
  const currentOpacity = d3.selectAll(`.${categoryClass}`).style('opacity')
  d3.selectAll(`.${categoryClass}`)
    .transition()
    .style('opacity', currentOpacity === '1' ? 0 : 1)
    .attr('pointer-events', currentOpacity === '1' ? 'none' : 'visible')
  d3.select(event.currentTarget)
    .transition()
    .style('font-weight', currentOpacity === '0' ? 'bold' : 'normal')
}

/** Hide or show all the elements for an "over"-category
 *
 * @param {MouseEvent} event - The event that triggered the hide or show
 * @param {object} d - The data to hide or show
 * @returns {void} - The function does not return anything
 */
function hideShowAllUnderlings (event, d) {
  const header = d3.select(event.currentTarget)
  const currentWeight = header.style('font-weight')

  header
    .transition()
    .style('font-weight', currentWeight === 'normal' ? 'bold' : 'normal')

  const parentGroup = d3.select(event.currentTarget.parentNode)
  const items = parentGroup.selectAll('.legend-item')

  items.each(function (d) {
    const textElement = d3.select(this).select('text')
    const itemWeight = textElement.style('font-weight')

    if (itemWeight === currentWeight) {
      hideShowCategory({ currentTarget: textElement.node() }, d)
    }
  })
}
