/**
 * Defines the contents of the tooltip. See CSS for tooltip styling.
 * The tooltip features the movie name, box office, total nominations,
 * rank, and release year.
 *
 * @param {object} d - The data associated to the hovered element
 * @param {string} mesureSucces - The selected success metric in which the graph will be dependant on
 * @param {Function} colorScale - The scale color to use
 * @returns {string} The tooltip contents
 */
export function getContents (d, mesureSucces, colorScale) {
  const LABEL_MATCH = {
    box_office: 'Box Office',
    profit: 'Profit Généré',
    rating: 'Classement IMDb',
    numNominations: 'Nombre de Nominations'
  }

  const KEY_MATCH = {
    Genre: 'Genre',
    Casts: 'Acteur',
    Directors: 'Réalisateur',
    Writers: 'Scénariste'
  }

  const str = d.category || ''
  const [key0, value] = str.split(':').map(s => s.trim())

  const key = KEY_MATCH[key0] || key0

  const successName = LABEL_MATCH[mesureSucces] || mesureSucces

  const topMovies = d.noms || []

  const movieList = topMovies.length
    ? topMovies.map(m => `<li>🎬 ${m}</li>`).join('')
    : '<li>No rated movies</li>'

  let html = `<div class="tooltip-value" style="
      z-index: 1000;
      background: rgba(255, 255, 255, 0.95);
      fontFamily: 'Segoe UI, sans-serif';
      padding: 12px;
      border-radius: 8px;
      color: '#222';
      lineHeight: '1.5';
      border: '1px solid #ccc';
      box-shadow: 0 2px 8px rgba(0,0,0,0.15);
      font-size: '13px',
      "
  >  `

  if (d.name !== undefined) {
    const unit = (mesureSucces === 'box_office' || mesureSucces === 'profit') ? '$' : ''
    const valeur = (mesureSucces === 'numNominations') ? d[mesureSucces] : d[mesureSucces].toFixed(2)

    html += `<div style="margin-bottom: 8px;">
              <strong style="font-size: 18px; color:#777">${d.name}</strong><br>
            </div>
            <div style="font-size: 15px;margin-top: 10px; border-top: 1px solid #eee; padding-top: 8px;">
              <strong>📅 Année:</strong> ${d.year}<br>
              <strong>⭐ ${successName}:</strong> ${valeur} ${unit}
            </div>`
  } else {
    const films = (d.count === 1) ? 'film' : 'films'
    html += `<div style="margin-bottom: 8px;">
              <strong style="font-size: 18px; color:${colorScale(d.category)}">${value}</strong><br>
              <span style="color: #666">${key}</span>
            </div>
            <div style="font-size: 15px;margin-top: 10px; border-top: 1px solid #eee; padding-top: 8px;">
              <strong>📅 Année:</strong> ${d.year}<br>
              <strong>⭐ Moyenne:</strong> ${d.average.toFixed(2)}%
            </div>
            <div style="margin-top: 10px; border-top: 1px solid #eee; padding-top: 8px;">
              <strong style="font-size: 16px; 
                              font-weight: bold; 
                              display: block; 
                              margin-bottom: 6px;"> ${d.count} ${films} cette année :</strong>
              <ul style="margin: 6px 0; font-size: 15px; padding-left: 18px;">${movieList}</ul>
            </div>`
  }

  html += '</div>'

  return html
}

/**
 * Sets up the hover event handler. The tooltip should show on on hover.
 *
 * @param {*} g The d3 Selection of the graph's g SVG element
 * @param {*} tip The tooltip
 */
export function setCircleHoverHandler (g, tip) {
  g.selectAll('.data-point, .ref-marker')
    .on('mouseover', function (e, d) {
      d3.select(this)
        .style('cursor', 'pointer')
        .attr('r', 6)
      tip.show(d, this)
    })
    .on('mouseout', function (e, d) {
      d3.select(this)
        .attr('r', 5)
      tip.hide(d, this)
    })
}
